const canvas=document.getElementById('kitchen'),ctx=canvas.getContext('2d');
let W=innerWidth,H=innerHeight,DPR=1,sceneTime=0;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const ingredients=[
 {id:'beans',name:'Kidney beans',short:'Beans',emoji:'🫘',icon:'◉',color:'#9a5743'},
 {id:'carrot',name:'Carrot',short:'Carrot',emoji:'🥕',icon:'♧',color:'#e38b45'},
 {id:'sausage',name:'Sausage',short:'Sausage',emoji:'🌭',icon:'▬',color:'#ad6847'},
 {id:'bread',name:'Bread roll',short:'Bread',emoji:'🍞',icon:'▰',color:'#d2a35a'},
 {id:'patty',name:'Beef patty',short:'Patty',emoji:'🥩',icon:'●',color:'#a64b3c'},
 {id:'tomato',name:'Tomato',short:'Tomato',emoji:'🍅',icon:'✿',color:'#c94e3d'}
];
const recipes=[
 {name:'Bean & Banger Stew',items:['beans','carrot','sausage'],icon:'♨'},
 {name:'Yardbird Sloppy Joe',items:['bread','patty','tomato'],icon:'▰'},
 {name:'Cellblock Chili',items:['beans','patty','tomato'],icon:'♨'},
 {name:'Midnight Sausage Hash',items:['sausage','carrot','bread'],icon:'✦'},
 {name:'Redbrick Breakfast',items:['bread','sausage','tomato'],icon:'☼'}
];
const inmates=[['THE PROFESSOR','♟'],['BIG MACK','♜'],['SLICK RICK','♞'],['MAD DOG','♟'],['OLD TIMER','♜'],['THE NEW KID','♞'],['IRON MIKE','♟']];
let state='title',order=null,orderIndex=0,orderTime=35,cookTime=0,pan=[],score=0,rep=0,lives=3,combo=0,shiftTime=0,last=0,toastTimer=0,soundOn=false,audio;
const $=id=>document.getElementById(id);
function renderIngredients(){ $('ingredient-list').innerHTML=ingredients.map((x,i)=>`<button class="ingredient-card" data-id="${x.id}" title="Add ${x.name} (${i+1})"><span class="ingredient-key">${i+1}</span><span class="ingredient-emoji">${x.emoji}</span><span class="ingredient-info"><b>${x.short}</b><small>ADD TO POT</small></span></button>`).join('');document.querySelectorAll('.ingredient-card').forEach((el,i)=>el.onclick=()=>addIngredient(el.dataset.id)); }
renderIngredients();
function makeOrder(){order=recipes[Math.floor(Math.random()*recipes.length)];const inmate=inmates[Math.floor(Math.random()*inmates.length)];$('meal-name').textContent=order.name;$('ticket-number').textContent='TICKET '+String(orderIndex+1).padStart(2,'0');$('portrait-name').textContent=inmate[0];$('customer-portrait').querySelector('.portrait-silhouette').textContent=inmate[1];orderTime=35;updateRecipe();updateHUD()}
function start(){state='ready';score=0;rep=0;lives=3;combo=0;orderIndex=0;shiftTime=0;pan=[];makeOrder();$('start-overlay').classList.add('hidden');$('end-overlay').classList.add('hidden');$('combo-text').textContent='FIRST SERVICE';updateHUD();renderPot();}
function updateRecipe(){ $('recipe-list').innerHTML=order.items.map(id=>{const x=ingredients.find(a=>a.id===id);const done=pan.includes(id);return `<div class="recipe-row ${done?'done':''}"><span class="recipe-icon">${done?'✓':x.icon}</span><span>${x.short}</span></div>`}).join('') }
function addIngredient(id){if(state!=='ready')return;if(pan.length>=3){toast('THAT POT IS FULL — CLEAR AN INGREDIENT');return}if(pan.includes(id)){toast('ONE OF EACH, WARDEN');return}pan.push(id);sound(430,.045);renderPot();updateRecipe();document.querySelectorAll('.ingredient-card').forEach(e=>e.classList.toggle('selected',pan.includes(e.dataset.id)));}
function removeIngredient(id){if(state!=='ready')return;pan=pan.filter(x=>x!==id);renderPot();updateRecipe();document.querySelectorAll('.ingredient-card').forEach(e=>e.classList.toggle('selected',pan.includes(e.dataset.id)));}
function renderPot(){const target=$('pot-contents');target.innerHTML=pan.length?pan.map(id=>{const x=ingredients.find(a=>a.id===id);return `<button class="pot-chip" data-id="${id}" title="Remove ${x.short}">${x.emoji} ${x.short} ×</button>`}).join(''):'<span class="empty-hint">Pick ingredients below</span>';target.querySelectorAll('.pot-chip').forEach(e=>e.onclick=()=>removeIngredient(e.dataset.id));$('board-food').innerHTML=pan.length?pan.map(id=>`<span class="board-ingredient">${ingredients.find(x=>x.id===id).emoji}</span>`).join(''):'<span class="board-placeholder">Your prep space</span>';$('pot-food').textContent=pan.length?order.icon:'∅';$('pot-label').textContent=pan.length?'FRESH INGREDIENTS':'EMPTY POT';const correct=order&&equal(pan,order.items);$('cook-button').disabled=state==='cooking'||state==='cooked';$('action-label').textContent=state==='cooking'?'SIMMERING…':state==='cooked'?'READY TO PLATE':correct?'LIGHT THE BURNER':pan.length===3?'CHECK THE RECIPE':'ADD 3 INGREDIENTS';if(state==='cooked'){$('serve-button').hidden=false;$('cook-button').hidden=true}else{$('serve-button').hidden=true;$('cook-button').hidden=false} }
function equal(a,b){return a.length===b.length&&a.every(x=>b.includes(x))}
function cook(){if(state!=='ready')return;if(!equal(pan,order.items)){toast(pan.length<3?'NEED THREE INGREDIENTS IN THE POT':'NOT THAT RECIPE, WARDEN');$('station-panel').classList.remove('shaking');void $('station-panel').offsetWidth;$('station-panel').classList.add('shaking');sound(120,.08);return}state='cooking';cookTime=0;$('heat-label').textContent='HEATING';$('heat-dot').parentElement.classList.add('hot');$('pot-window').classList.add('is-hot');$('pot-status').textContent='KEEP AN EYE ON THE POT';sound(160,.11);renderPot();}
function serve(){if(state!=='cooked')return;const tip=Math.ceil(orderTime*1.25),clean=orderTime>20?10:0,comboBonus=combo*5;score+=100+tip+clean+comboBonus;rep+=1;combo++;orderIndex++;toast(`CLEAN PLATE! +${100+tip+clean+comboBonus} PAYOFF${combo>1?' · '+combo+'× STREAK':''}`);sound(640,.16);if(combo===2)$('combo-text').textContent='NICE LITTLE STREAK';else if(combo>=3)$('combo-text').textContent=combo+'× HOT STREAK';else $('combo-text').textContent='FIRST SERVICE';setTimeout(()=>{if(state!=='cooked')return;pan=[];state='ready';cookTime=0;$('heat-label').textContent='COLD';$('heat-dot').parentElement.classList.remove('hot');$('pot-window').classList.remove('is-hot');$('pot-status').textContent='READY WHEN YOU ARE';makeOrder();renderPot();document.querySelectorAll('.ingredient-card').forEach(e=>e.classList.remove('selected'));},650);updateHUD()}
function miss(){lives--;combo=0;$('combo-text').textContent=lives?'KEEP THE LINE MOVING':'LAST MEAL';toast(lives?'ORDER EXPIRED — ONE STRIKE':'SHIFT OVER — THE YARD LOST PATIENCE');sound(100,.22);updateHUD();if(lives<=0){setTimeout(()=>endGame(false),900)}else{pan=[];state='ready';cookTime=0;$('heat-label').textContent='COLD';$('heat-dot').parentElement.classList.remove('hot');$('pot-window').classList.remove('is-hot');$('pot-status').textContent='READY WHEN YOU ARE';setTimeout(()=>{if(state==='ready'){makeOrder();renderPot();document.querySelectorAll('.ingredient-card').forEach(e=>e.classList.remove('selected'))}},900)}}
function endGame(won){state='over';$('end-title').textContent=won?'SHIFT'S OVER':'SHIFT'S OVER';$('end-message').textContent=score>=600?'Word got around. Even the warden's impressed.':score>=250?'Not bad, chef. The yard will remember.':'The yard wanted seconds. You know the drill.';$('end-icon').textContent=score>=500?'✦':'♨';$('final-score').textContent=String(score).padStart(3,'0');$('final-rep').textContent=rep;$('end-overlay').classList.remove('hidden')}
function updateHUD(){$('cash').textContent=String(score).padStart(3,'0');$('rep').textContent=rep;$('order-timer').textContent=Math.max(0,Math.ceil(orderTime));$('timer-fill').style.width=Math.max(0,orderTime/35*100)+'%';$('timer-fill').classList.toggle('low',orderTime<10)}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function sound(freq,duration){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
$('start-button').onclick=start;$('restart-button').onclick=start;$('cook-button').onclick=cook;$('serve-button').onclick=serve;$('clear-button').onclick=()=>{if(state==='ready'){pan=[];renderPot();updateRecipe();document.querySelectorAll('.ingredient-card').forEach(e=>e.classList.remove('selected'))}};$('sound-toggle').onclick=()=>{soundOn=!soundOn;$('sound-toggle').classList.toggle('active',soundOn);if(soundOn)sound(500,.08)};
addEventListener('keydown',e=>{if(e.key==='Enter'&&state==='title')start();if(e.key==='Escape'&&state==='title')start();if(state==='ready'&&e.key>='1'&&e.key<='6')addIngredient(ingredients[+e.key-1].id);if(e.key===' '){e.preventDefault();if(state==='ready')cook();else if(state==='cooked')serve()}});
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;sceneTime+=dt;if(state==='ready'||state==='cooking'||state==='cooked'){shiftTime+=dt;if(state==='ready'){orderTime-=dt;if(orderTime<=0){orderTime=0;miss()}}if(state==='cooking'){cookTime+=dt;$('cook-fill').style.width=Math.min(100,cookTime/3.2*100)+'%';if(cookTime>=3.2){state='cooked';$('pot-status').textContent='PERFECT — READY TO PLATE';$('heat-label').textContent='DONE';$('action-label').textContent='READY TO PLATE';$('serve-button').hidden=false;$('cook-button').hidden=true;sound(720,.13);toast('THAT'S COOKED TO PERFECTION');}}$('shift-time').textContent=String(Math.floor(shiftTime/60)).padStart(2,'0')+':'+String(Math.floor(shiftTime%60)).padStart(2,'0');updateHUD()}drawScene();requestAnimationFrame(frame)}requestAnimationFrame(frame);
function drawScene(){ctx.clearRect(0,0,W,H);const scale=Math.max(W/1280,H/720);ctx.save();ctx.translate((W-1280*scale)/2,(H-720*scale)/2);ctx.scale(scale,scale);const g=ctx.createLinearGradient(0,0,0,720);g.addColorStop(0,'#303a35');g.addColorStop(.52,'#4b4d40');g.addColorStop(1,'#202724');ctx.fillStyle=g;ctx.fillRect(0,0,1280,720);
// Back wall blocks
for(let row=0;row<8;row++){for(let col=-1;col<14;col++){let x=col*100+(row%2)*50;let y=79+row*43;ctx.fillStyle=(row+col)%3===0?'#39423b':(row+col)%3===1?'#42483e':'#343e38';ctx.fillRect(x,y,98,41);ctx.fillStyle='#242d29';ctx.fillRect(x,y+39,98,3);ctx.fillRect(x+97,y,3,43)}}
// Back window / moonlight
ctx.fillStyle='#192725';ctx.fillRect(526,114,228,147);ctx.fillStyle='#293c3b';ctx.fillRect(536,123,208,129);ctx.fillStyle='#d5cc9d';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(690,158,17,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#526362';ctx.fillRect(536,207,208,45);ctx.fillStyle='#26312e';ctx.fillRect(536,211,208,4);ctx.fillRect(536,232,208,4);for(let x=552;x<740;x+=35){ctx.fillRect(x,123,5,129)}ctx.fillStyle='#18221f';ctx.fillRect(516,108,8,159);ctx.fillRect(756,108,8,159);ctx.fillRect(516,108,248,8);ctx.fillRect(516,259,248,8);
// brick wall detail/stencil
ctx.fillStyle='#c2b384';ctx.font='10px monospace';ctx.globalAlpha=.42;ctx.fillText('BLOCK C',180,153);ctx.fillText('NO TALKING',966,152);ctx.fillStyle='#c9824d';ctx.beginPath();ctx.arc(1033,135,4,0,7);ctx.fill();ctx.globalAlpha=1;
// Pipes
ctx.strokeStyle='#202b27';ctx.lineWidth=11;ctx.beginPath();ctx.moveTo(106,82);ctx.lineTo(106,322);ctx.lineTo(236,322);ctx.stroke();ctx.strokeStyle='#576054';ctx.lineWidth=2;ctx.stroke();ctx.beginPath();ctx.moveTo(107,209);ctx.lineTo(187,209);ctx.stroke();ctx.fillStyle='#828064';ctx.fillRect(95,200,24,7);
// Steel shelf and jars
ctx.fillStyle='#202a27';ctx.fillRect(853,273,286,9);ctx.fillStyle='#788074';ctx.fillRect(853,281,286,4);for(let i=0;i<5;i++){let x=870+i*49;ctx.fillStyle=i%2?'#65715c':'#88744f';ctx.fillRect(x,236,30,37);ctx.fillStyle='#a99a6e';ctx.fillRect(x-2,231,34,6);ctx.fillStyle='#c1b28855';ctx.fillRect(x+5,242,3,25)}
// Hanging ladles
for(let i=0;i<4;i++){let x=797+i*36;ctx.strokeStyle='#988c6b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,202);ctx.lineTo(x,226);ctx.stroke();ctx.beginPath();ctx.ellipse(x,231,5,7,0,0,7);ctx.stroke()}
// Left stove body
ctx.fillStyle='#222a26';ctx.fillRect(274,365,187,94);ctx.fillStyle='#596057';ctx.fillRect(270,356,195,15);ctx.fillStyle='#303934';ctx.fillRect(284,371,169,74);for(let i=0;i<3;i++){ctx.fillStyle='#111817';ctx.beginPath();ctx.ellipse(313+i*57,376,25,9,0,0,7);ctx.fill();ctx.strokeStyle='#74725f';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(313+i*57,376,18,6,0,0,7);ctx.stroke()}for(let i=0;i<3;i++){ctx.fillStyle='#9e8c67';ctx.beginPath();ctx.arc(304+i*57,427,5,0,7);ctx.fill();ctx.fillStyle='#b65137';ctx.beginPath();ctx.arc(304+i*57,427,2,0,7);ctx.fill()}
// Right sink
ctx.fillStyle='#313a35';ctx.fillRect(791,369,217,72);ctx.fillStyle='#899083';ctx.fillRect(784,360,232,13);ctx.fillStyle='#222a27';ctx.beginPath();ctx.ellipse(895,378,84,20,0,0,7);ctx.fill();ctx.strokeStyle='#828776';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(895,377,73,14,0,0,7);ctx.stroke();ctx.strokeStyle='#a2a083';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(895,351);ctx.lineTo(895,331);ctx.quadraticCurveTo(895,322,906,322);ctx.lineTo(925,322);ctx.stroke();ctx.fillStyle='#73847a';ctx.fillRect(921,319,11,6);
// floor perspective
ctx.fillStyle='#252d29';ctx.beginPath();ctx.moveTo(0,458);ctx.lineTo(1280,458);ctx.lineTo(1280,720);ctx.lineTo(0,720);ctx.fill();ctx.strokeStyle='#39423a';ctx.lineWidth=2;for(let i=0;i<9;i++){let y=470+i*i*3.4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1280,y);ctx.stroke()}for(let x=0;x<=1280;x+=130){ctx.beginPath();ctx.moveTo(640,458);ctx.lineTo(x,720);ctx.stroke()}
// stove fire glow
if(state==='cooking'||state==='cooked'){let glow=ctx.createRadialGradient(627,500,10,627,500,225);glow.addColorStop(0,'#d9813b23');glow.addColorStop(1,'#d9813b00');ctx.fillStyle=glow;ctx.fillRect(350,320,550,340)}
// subtle atmospheric lighting
const glow=ctx.createRadialGradient(640,370,60,640,370,500);glow.addColorStop(0,'#e3bd7830');glow.addColorStop(1,'#e3bd7800');ctx.fillStyle=glow;ctx.fillRect(0,60,1280,650);
// film grain flecks
for(let i=0;i<34;i++){const x=((i*197+Math.sin(sceneTime*.3+i)*8)%1280),y=((i*127+sceneTime*3)%710);ctx.fillStyle=i%3?'#e4d8b30a':'#080d0c18';ctx.fillRect(x,y,2,2)}ctx.restore()}

